import { recipe } from './detail-helpers-v1.js';
import { settlementTypes } from './economy-settlements.js';
const orderNotes='The quantity is checked against the order.|A written estimate is requested first.|The buyer supplies the reference sample.|Collection follows the next market day.|The keeper retains a copy of the request.|The dimensions must match the previous order.|A receipt is needed for the buyer.|The buyer confirms the collection time.|The order awaits a final specification.|The customer approves substitutions in advance.';
const enquiries='A repeat request from {customer} concerns {product}.|An estimate for {customer} covers {product}.|A reserved order for {customer} names {product}.|The collection list for {customer} includes {product}.|The current enquiry from {customer} concerns {product}.|A written request from {customer} specifies {product}.|An unfinished order for {customer} concerns {product}.|A sample request from {customer} names {product}.|The order book lists {product} for {customer}.|A scheduled collection by {customer} concerns {product}.';
export const demandRecipes=Object.fromEntries(Object.entries(settlementTypes).map(([key,p])=>[key,recipe(enquiries.split('|').map(v=>`At {displayName} in this ${p.label}: ${v}`),orderNotes)]));
const restockNotes='The next order needs a weight check.|A replacement batch must match the sample.|The supplier must confirm the quantity.|The order awaits a collection time.|The receiving ledger needs a second signature.|A sealed sample accompanies the order.|The keeper compares the current estimate.|The delivery must cite the earlier invoice.|A reserve quantity is set aside.|The invoice lists the responsible carrier.';
const supplyNotes='Materials for {trade} work include {material}.|The next {trade} order needs {material}.|The supply ledger lists {material} for {trade} work.|A customer’s {trade} request depends on {material}.|The sample record includes {material} for {trade} orders.|A repeat {trade} order calls for {material}.|The keeper is checking {material} for {trade} work.|A reserved {trade} order awaits {material}.|The receiving list names {material} for {trade} work.|The stock estimate covers {material} for {trade} orders.';
export const supplyRecipes=recipe(supplyNotes,restockNotes);
const requestNotes='asks about {product} at {displayName}|compares notes on {trade} work in {district}|checks an order for {product}|carries a sample for a {trade} commission|looks for a supplier of {material}|brings a message about {product}|checks a delivery through {supplyRoute}|asks who handles {trade} orders in {district}|compares an estimate for {product}|records a request for {product}';
export const guestRecipes=Object.fromEntries(Object.entries(settlementTypes).map(([key,p])=>[key,recipe(p.customers.map(c=>`A visitor representing ${c}`),requestNotes)]));
